# -*- coding: utf-8 -*-
"""
This library provides an easy way of decorating existing subroutines to include aliasing
functionality. This comes in handy mainly when implementing Robot Framework keywords, so
that the users of the keywords don't have to manage instances of objects via bulky
variables.

For example, the following method::

    def send_command(self, command, connection=None):
        ...

... would require the enduser to pass a connection object as it's ``connection``
parameter. If used in Robot Framework, the code gets a bit messier than it needs to::

    ${mail_server}=       New connection object   <some arguments>
    ${some_other_host}=   New connection object   <some arguments>
    Send command   ${first_command}    ${mail_server}
    Send command   ${second_command}   ${some_other_host}

With this library you can decorate the method without changing it's code,
in a backwards-compatible manner, such that the user can pass a string instead::

    New connection object   <some arguments>   alias=MailServer
    New connection object   <some arguments>   alias=SomeOtherHost
    Send command   ${first_command}    MailServer
    Send command   ${second_command}   SomeOtherHost

Afterwards, the user can use both approaches, so the decorated version will not break
existing code. The decorator will handle looking up of the correct instance in the alias
store you specified, and pass it instead of the string that was used by the user.

Python example
==============

The following code shows an example of an implementation of a Robot Framework
interface class::

    class Animal:
        def __init__(self, favourite_food):
            self.favourite_food = favourite_food


    class Zoo:
        def new_animal(self, favourite_food):
            return Animal(favourite_food)

        def feed(self, food, animal):
            print("I'm giving {} to {}.".format(food, animal)

        def get_favourite_food(self, animal):
            return animal.favourite_food

Methods ``feed`` and ``get_favourite_food`` take an instance of ``Animal`` as a
parameter. Method ``new_instance`` creates these instances.

To let users refer to the instances with aliases (strings), the following has
to be be done:

* Add a lookup handler instance as a static field to your class (so that it is
  possible to decorate methods with it).
* Make creational methods in your class add new instances to the store
  (possibly add a keyword argument that will let users pass the desired alias).
* Decorate methods with LookupHandler.implicit_lookup where applicable.


This is the previously shown code after these modifications::

    from taf.internal.aliasing import aliasing_scope


    class Animal:
        def __init__(self, favourite_food):
            self.favourite_food = favourite_food


    class Zoo:
        lookup_handler, store = aliasing_scope()

        def new_animal(self, favourite_food, name=None):
            new_animal = Animal(favourite_food)
            self.store.add(new_animal, name)
            return new_animal

        @lookup_handler.implicit_lookup
        def feed(self, food, animal):
            print("Im giving {} to {}.".format(food, animal))

        @lookup_handler.implicit_lookup
        def get_favourite_food(self, animal):
            return animal.favourite_food


Previously, to use these keywords in Robot Framework, you would have to do
this::

    ${animal}=    New animal    beef
    ${food}=      Get favourite food
    Feed          ${food}       ${animal}

After the aforementioned modifications, these keywords can be used in the
following way::

    New animal    beef                    Lion
    ${food}=      Get favourite food      Lion
    Feed          ${food}                 Lion
"""
from .exceptions import AliasLookupError
from .lookup_handlers import LookupHandler
from .stores import Store, AliasStore, SeparateDefaultAliasStore


__all__ = ['AliasLookupError', 'LookupHandler', 'SeparateDefaultAliasStore',
           'AliasStore', 'Store']


def aliasing_scope(lookup_arg=None, lookup_type=None, name=None):
    """Create a working handler and a store.

    See :class:`LookupHandler` docstring for description of ``lookup_arg`` and
    ``lookup_type`` parameters.
    See :class:`AliasStore` docstring for description of the ``name`` parameter.

    Returns a working :class:`.LookupHandler` and its `store`_.
    """
    handler = LookupHandler(lookup_arg=lookup_arg, lookup_type=lookup_type)
    store = AliasStore(name=name)
    handler.store = store
    return handler, store
